// The civ7 renderer's buffers. Storage keeps shared/ring.js offsets for everything the PC and
// the console runtime read or write (publication, UI block, frames, UI pages), so only the GPU
// side changes between renderers. README.md, "Layout".
import * as ring from '../../streamer/shared/ring.js';

export const ABI = 2;
export const WIDTH = 1920;
export const HEIGHT = 1080;
export const INPUT_BYTES = 4096;
export const STORAGE_BYTES = ring.MEMORY_BYTES;
export const FRAME_BYTES = ring.FRAME_BYTES;
export const FRAME_COUNT = ring.NATIVE_FRAMES;
export const FRAMES_OFFSET = ring.FRAMES_OFFSET;
export const UI_OFFSET = ring.UI_OFFSET;
export const UI_PAGE_BYTES = ring.UI_PAGE_BYTES;
export const UI_PAGE_COUNT = ring.UI_PAGES;
export const NATIVE_ABI = ring.NATIVE_ABI;
export const UI_MAGIC = ring.UI_MAGIC;
export const MODE = {none: 0, native: ring.MODE.native};

/** The control words the renderer's shaders read; frameCounter is renderer-private. */
export const CONTROL = {
  mode: ring.CONTROL.mode, current: ring.CONTROL.current, size: ring.CONTROL.size,
  currentStride: ring.CONTROL.currentStride, currentSliceHeight: ring.CONTROL.currentSliceHeight,
  currentColor: ring.CONTROL.currentColor, nativeReady: ring.CONTROL.nativeReady,
  nativeApplied: ring.CONTROL.nativeApplied, nativeSequence: ring.CONTROL.nativeSequence,
  nativeIndex: ring.CONTROL.nativeIndex, nativeWidth: ring.CONTROL.nativeWidth,
  nativeHeight: ring.CONTROL.nativeHeight, nativeStride: ring.CONTROL.nativeStride,
  nativeSliceHeight: ring.CONTROL.nativeSliceHeight, nativeColor: ring.CONTROL.nativeColor,
  nativeCommit: ring.CONTROL.nativeCommit, frameCounter: 512
};
export const UI = ring.UI;

/** Where createInputReader writes the pad and touch state, then the compute shader's scratch. */
export const INPUT = {pad: 0, touch: 128, previousButtons: 784, chordFrames: 788, stickRepeat: 792, touchHeld: 796};

/** Background, 24 covers, 48 text strips, 32 items or cursor, the busy indicator. */
export const UI_INSTANCES = 106;
/** The rate badge quad follows the page instances. */
export const BADGE_INSTANCE = UI_INSTANCES;

/**
 * The two streaming frame slots the host publishes into directly; a draw's first instance
 * names its slot. Byte offsets in storage, above the legacy written[] range.
 */
export const VIDEO_SLOTS = 2;
export const VIDEO = {base: 0xb000, slotBytes: 32, sequence: 0, width: 4, height: 8, stride: 12, sliceHeight: 16,
  color: 20};

/** The badge rectangle in display pixels and its RGBA pixels in the third frame slot. */
export const BADGE = {visible: 0xb100, x: 0xb104, y: 0xb108, width: 0xb10c, height: 0xb110};
export const BADGE_OFFSET = ring.frameOffset(2);

/**
 * Active drawing size and retained backing extent. Startup writes both; mode changes update
 * the active size. Page and badge rects stay in WIDTH x HEIGHT. README.md, "Target".
 */
export const TARGET = {width: 0xb120, height: 0xb124, backingWidth: 0xb128, backingHeight: 0xb12c};
export const BADGE_BYTES = 960 * 64 * 4;

export const STAGES = {
  publish: 'publish.comp', videoVertex: 'video.vert', videoFragment: 'video.frag',
  videoStorageFragment: 'video-storage.frag', uiVertex: 'ui.vert', uiFragment: 'ui.frag'
};

/** @param {number} index */
export function frameOffset(index) {
  if (!Number.isInteger(index) || index < 0 || index >= FRAME_COUNT) throw Error('Invalid video frame slot');
  return ring.frameOffset(index);
}

/** @param {string} name */
const constant = name => name.replace(/[A-Z]/g, letter => '_' + letter).toUpperCase();

export function glslLayout() {
  const words = Object.entries({...CONTROL, ...UI})
    .map(([name, offset]) => `const uint ${constant(name)} = ${offset / 4}u;`);
  const input = Object.entries(INPUT)
    .map(([name, offset]) => `const uint INPUT_${constant(name)} = ${offset / 4}u;`);
  const {base, slotBytes, ...fields} = VIDEO;
  const video = Object.entries(fields).map(([name, offset]) => `const uint SLOT_${constant(name)} = ${offset / 4}u;`);
  const badge = Object.entries(BADGE).map(([name, offset]) => `const uint BADGE_${constant(name)} = ${offset / 4}u;`);
  const target = Object.entries(TARGET).map(([name, offset]) => `const uint TARGET_${constant(name)} = ${offset / 4}u;`);
  return ['// Generated by civ7/layout.js.', ...words, ...input, ...video, ...badge, ...target,
    `const uint VIDEO_BASE = ${base / 4}u;`, `const uint VIDEO_SLOT_WORDS = ${slotBytes / 4}u;`,
    `const uint BADGE_PIXELS = ${BADGE_OFFSET / 4}u;`,
    `const uint FRAME_BYTES = ${FRAME_BYTES}u;`, `const uint FRAME_COUNT = ${FRAME_COUNT}u;`,
    `const uint FRAMES_OFFSET = ${FRAMES_OFFSET}u;`, `const uint MODE_NATIVE = ${MODE.native}u;`,
    `const uint UI_BASE = ${UI_OFFSET / 4}u;`, `const uint UI_PAGE_WORDS = ${UI_PAGE_BYTES / 4}u;`,
    `const uint UI_PROTOCOL_MAGIC = ${UI_MAGIC}u;`, `const uint NATIVE_ABI = ${NATIVE_ABI}u;`,
    `const vec2 DISPLAY_SIZE = vec2(${WIDTH}, ${HEIGHT});`, ''].join('\n');
}
